/**
 * Rolling-origin backtest on synthetic ledgers with known ground truth.
 *
 * What this does and does not show: the ground truth is generated by `sim/generator.ts`, so the
 * results measure whether the estimator is calibrated *when its assumptions hold* and how it degrades
 * when they do not (log-logistic noise, batch payers). They are NOT evidence about real PayPal
 * merchants. Real-merchant validation needs the merchant's own history.
 */
import type { BacktestReport } from '../../shared/types';
import { DAY_MS, clamp } from './math';
import { fitModel, makePredictive, type FittedModel, type Observation } from './model';
import { generateLedger, type Family, type GeneratedInvoice } from '../sim/generator';

const LEVELS = [0.1, 0.25, 0.5, 0.75, 0.9];

interface Acc {
  pit: number[];
  nPit: number;
  inInt: Record<'50' | '80' | '90', number>;
  pin: { model: number; payer: number; global: number; due: number };
  mae: { model: number; payer: number; global: number; due: number };
  n: number;
  ghost: { predSum: number; obsSum: number; brier: number; brierBase: number; n: number };
}

const newAcc = (): Acc => ({
  pit: new Array(10).fill(0),
  nPit: 0,
  inInt: { '50': 0, '80': 0, '90': 0 },
  pin: { model: 0, payer: 0, global: 0, due: 0 },
  mae: { model: 0, payer: 0, global: 0, due: 0 },
  n: 0,
  ghost: { predSum: 0, obsSum: 0, brier: 0, brierBase: 0, n: 0 },
});

const pinball = (tau: number, y: number, q: number) => Math.max(tau * (y - q), (tau - 1) * (y - q));

function asOf(inv: GeneratedInvoice, t0: number): Observation | null {
  if (inv.sentAt >= t0) return null;
  return {
    invoiceId: inv.id,
    payerId: inv.payerId,
    sentAt: inv.sentAt,
    netDays: inv.netDays,
    amount: inv.amount,
    paidAt: inv.paidAt !== null && inv.paidAt <= t0 ? inv.paidAt : null,
    reminders: inv.reminders.filter((r) => r <= t0),
  };
}

function empiricalQuantile(sortedAsc: number[], p: number): number {
  const idx = clamp(p * (sortedAsc.length - 1), 0, sortedAsc.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  return sortedAsc[lo] + (sortedAsc[hi] - sortedAsc[lo]) * (idx - lo);
}

function evaluateOrigin(acc: Acc, all: GeneratedInvoice[], t0: number) {
  const obs = all.map((i) => asOf(i, t0)).filter((o): o is Observation => o !== null);
  const model = fitModel(obs, t0);
  // baseline 1: no payer information (one shared payer)
  const globalModel: FittedModel = fitModel(
    obs.map((o) => ({ ...o, payerId: '__all__' })),
    t0,
  );
  // baseline 2: payer empirical quantiles of days-to-pay from that payer's paid history
  const paidByPayer = new Map<string, number[]>();
  for (const o of obs) {
    if (o.paidAt !== null) {
      const arr = paidByPayer.get(o.payerId) ?? [];
      arr.push((o.paidAt - o.sentAt) / DAY_MS);
      paidByPayer.set(o.payerId, arr);
    }
  }
  const ghostBase = model.ghost0;

  for (const inv of all) {
    const o = asOf(inv, t0);
    if (!o || o.paidAt !== null) continue;
    const age = (t0 - inv.sentAt) / DAY_MS;
    if (age > model.config.ghostHorizonDays) continue;
    const input = { payerId: inv.payerId, netDays: inv.netDays, amount: inv.amount, sentAt: inv.sentAt, reminders: o.reminders };
    const pred = makePredictive(model, input, t0);
    const gp = pred.ghostProb;
    const isGhost = !Number.isFinite(inv.trueT);

    // ghost calibration
    acc.ghost.n += 1;
    acc.ghost.predSum += gp;
    acc.ghost.obsSum += isGhost ? 1 : 0;
    acc.ghost.brier += (gp - (isGhost ? 1 : 0)) ** 2;
    acc.ghost.brierBase += (ghostBase - (isGhost ? 1 : 0)) ** 2;

    if (isGhost) continue; // payment-time scoring is conditional on the invoice eventually being paid
    const y = inv.trueT;
    if (y <= age) continue; // cannot happen unless paid exactly now; guard anyway
    const pay = 1 - gp;
    if (pay <= 1e-9) continue;
    const u = clamp(pred.cdfDays(y) / pay, 0, 1 - 1e-12);
    acc.pit[Math.min(9, Math.floor(u * 10))] += 1;
    acc.nPit += 1;
    if (u >= 0.25 && u <= 0.75) acc.inInt['50'] += 1;
    if (u >= 0.1 && u <= 0.9) acc.inInt['80'] += 1;
    if (u >= 0.05 && u <= 0.95) acc.inInt['90'] += 1;

    const gpred = makePredictive(globalModel, { ...input, payerId: '__all__' }, t0);
    const emp = (paidByPayer.get(inv.payerId) ?? []).filter((t) => t > age).sort((a, b) => a - b);
    const due = Math.max(inv.netDays, age);

    let sumM = 0, sumP = 0, sumG = 0, sumD = 0;
    for (const tau of LEVELS) {
      const qm = pred.quantileDays(tau * pay);
      const gpay = 1 - gpred.ghostProb;
      const qg = gpred.quantileDays(tau * gpay);
      const qp = emp.length >= 4 ? empiricalQuantile(emp, tau) : qg;
      sumM += pinball(tau, y, qm);
      sumP += pinball(tau, y, qp);
      sumG += pinball(tau, y, qg);
      sumD += pinball(tau, y, due);
    }
    acc.pin.model += sumM / LEVELS.length;
    acc.pin.payer += sumP / LEVELS.length;
    acc.pin.global += sumG / LEVELS.length;
    acc.pin.due += sumD / LEVELS.length;
    const m50 = pred.quantileDays(0.5 * pay);
    const g50 = gpred.quantileDays(0.5 * (1 - gpred.ghostProb));
    const p50 = emp.length >= 4 ? empiricalQuantile(emp, 0.5) : g50;
    acc.mae.model += Math.abs(m50 - y);
    acc.mae.global += Math.abs(g50 - y);
    acc.mae.payer += Math.abs(p50 - y);
    acc.mae.due += Math.abs(due - y);
    acc.n += 1;
  }
}

export interface BacktestScenario {
  name: string;
  description: string;
  family: Family;
  reminderProb: number;
  seeds: number[];
}

export const SCENARIOS: BacktestScenario[] = [
  { name: 'well-specified', description: 'Log-normal truth, no reminders: the estimator\'s home turf.', family: 'lognormal', reminderProb: 0, seeds: [101, 102, 103, 104, 105, 106] },
  { name: 'misspecified-loglogistic', description: 'Log-logistic (heavier-tailed) truth, no reminders: the model assumes log-normal.', family: 'loglogistic', reminderProb: 0, seeds: [201, 202, 203, 204, 205, 206] },
  { name: 'misspecified-batch', description: 'Payers settle in 15-day batch cycles (multi-modal): the model assumes a smooth log-normal.', family: 'batch', reminderProb: 0, seeds: [301, 302, 303, 304, 305, 306] },
];

export function runScenario(sc: BacktestScenario, now = Date.UTC(2026, 9, 17)): BacktestReport {
  const acc = newAcc();
  let nTrain = 0;
  for (const seed of sc.seeds) {
    const { invoices } = generateLedger({ now, seed, family: sc.family, reminderProb: sc.reminderProb, historyDays: 540, recentBoost: 1.2 });
    nTrain += invoices.length;
    for (let back = 240; back >= 30; back -= 30) evaluateOrigin(acc, invoices, now - back * DAY_MS);
  }
  const n = Math.max(1, acc.n);
  const nPit = Math.max(1, acc.nPit);
  return {
    generatedAt: Date.now(),
    scenario: sc.name,
    description: sc.description,
    nTrain: Math.round(nTrain / sc.seeds.length),
    nTest: acc.n,
    coverage: [
      { nominal: 0.5, observed: acc.inInt['50'] / nPit },
      { nominal: 0.8, observed: acc.inInt['80'] / nPit },
      { nominal: 0.9, observed: acc.inInt['90'] / nPit },
    ],
    pitHistogram: acc.pit.map((c) => c / nPit),
    pinball: {
      model: acc.pin.model / n,
      payerMedianBaseline: acc.pin.payer / n,
      globalBaseline: acc.pin.global / n,
      dueDateBaseline: acc.pin.due / n,
    },
    maeMedianDays: {
      model: acc.mae.model / n,
      payerMedianBaseline: acc.mae.payer / n,
      globalBaseline: acc.mae.global / n,
      dueDateBaseline: acc.mae.due / n,
    },
    kappa: null,
    ghost: {
      meanPredicted: acc.ghost.predSum / Math.max(1, acc.ghost.n),
      observed: acc.ghost.obsSum / Math.max(1, acc.ghost.n),
      brierModel: acc.ghost.brier / Math.max(1, acc.ghost.n),
      brierBaseRate: acc.ghost.brierBase / Math.max(1, acc.ghost.n),
      n: acc.ghost.n,
    },
    notes: [],
  };
}

/** Nudge-effect recovery: does the stage-2 posterior bracket the true reminder responsiveness? */
export function runNudgeRecovery(seeds = [401, 402, 403, 404, 405, 406, 407, 408], now = Date.UTC(2026, 9, 17)) {
  const rows: { truth: number; estimate: number; lo: number; hi: number; nObs: number }[] = [];
  for (const seed of seeds) {
    const { invoices } = generateLedger({ now, seed, family: 'lognormal', reminderProb: 0.6, historyDays: 540 });
    const obs: Observation[] = invoices.map((i) => ({
      invoiceId: i.id,
      payerId: i.payerId,
      sentAt: i.sentAt,
      netDays: i.netDays,
      amount: i.amount,
      paidAt: i.paidAt,
      reminders: i.reminders,
    }));
    const model = fitModel(obs, now);
    // truth: average first-reminder kappa among reminded invoices that were unpaid when reminded and
    // that pay later (the same population the estimator uses), on the log scale.
    const treated = invoices.filter((i) => i.reminders.length > 0 && !i.ghost);
    const truth = Math.exp(treated.reduce((a, i) => a + Math.log(i.kappa), 0) / Math.max(1, treated.length));
    rows.push({ truth, estimate: model.nudge.kappa, lo: model.nudge.lo, hi: model.nudge.hi, nObs: model.nudge.nObs });
  }
  return rows;
}

export function toMarkdown(reports: BacktestReport[], nudge: ReturnType<typeof runNudgeRecovery>): string {
  const f = (x: number, d = 2) => x.toFixed(d);
  const lines: string[] = [];
  lines.push('# Tidewater backtest (synthetic ground truth)', '');
  lines.push(
    '> **Read this first.** Every number below comes from *synthetic* ledgers whose ground truth is known. They show whether the estimator is calibrated when its assumptions hold, and how it degrades when they do not. They are **not** evidence about real PayPal merchants.',
    '',
  );
  lines.push('Method: rolling origin (9 monthly origins x 6 random ledgers per scenario). At each origin the model is refit using only data visible at that date; each invoice still open at the origin is scored against its realised payment time. Payment-time scores are conditional on the invoice eventually being paid; ghost (never-pays) probability is scored separately.', '');
  for (const r of reports) {
    lines.push(`## ${r.scenario}`, '', r.description, '');
    lines.push(`Scored invoices: ${r.nTest} (mean ledger size ${r.nTrain}).`, '');
    lines.push('| Interval | Nominal | Observed |', '|---|---|---|');
    for (const c of r.coverage) lines.push(`| central ${Math.round(c.nominal * 100)}% | ${Math.round(c.nominal * 100)}% | ${f(c.observed * 100, 1)}% |`);
    lines.push('');
    lines.push('| Forecaster | Mean pinball loss (days) | MAE of median (days) |', '|---|---|---|');
    lines.push(`| **Tidewater model** | **${f(r.pinball.model)}** | **${f(r.maeMedianDays.model)}** |`);
    lines.push(`| Payer empirical quantiles | ${f(r.pinball.payerMedianBaseline)} | ${f(r.maeMedianDays.payerMedianBaseline)} |`);
    lines.push(`| Global model (no payer info) | ${f(r.pinball.globalBaseline)} | ${f(r.maeMedianDays.globalBaseline)} |`);
    lines.push(`| Invoice due date | ${f(r.pinball.dueDateBaseline)} | ${f(r.maeMedianDays.dueDateBaseline)} |`);
    lines.push('');
    if (r.ghost) {
      lines.push(`Ghost (never-pays) probability: mean predicted ${f(r.ghost.meanPredicted * 100, 1)}% vs observed ${f(r.ghost.observed * 100, 1)}%; Brier ${f(r.ghost.brierModel, 4)} vs base-rate ${f(r.ghost.brierBaseRate, 4)} (n=${r.ghost.n}).`, '');
    }
    lines.push('PIT histogram (10 bins, uniform = 0.10 each): ' + r.pitHistogram.map((x) => f(x, 2)).join(' '), '');
  }
  lines.push('## Reminder-effect recovery (kappa)', '');
  lines.push('Ledgers with a 60%-probability merchant reminder policy. `truth` is the geometric mean of the true per-invoice kappa over reminded, eventually-paid invoices; the estimator only sees reminder dates and payment dates.', '');
  lines.push('| Seed | n obs | Truth | Estimate | 80% interval | Covered |', '|---|---|---|---|---|---|');
  nudge.forEach((r, i) => lines.push(`| ${i + 1} | ${r.nObs} | ${f(r.truth)} | ${f(r.estimate)} | ${f(r.lo)}-${f(r.hi)} | ${r.truth >= r.lo && r.truth <= r.hi ? 'yes' : 'no'} |`));
  const cov = nudge.filter((r) => r.truth >= r.lo && r.truth <= r.hi).length;
  lines.push('', `Truth fell inside the 80% interval in ${cov}/${nudge.length} runs. The prior is centred on kappa = 1 (no effect), so with little data the estimate is pulled toward "reminders do nothing".`, '');
  return lines.join('\n');
}
